    segments = sqlSegmentsMetadataManager
        .forceUpdateDataSourcesSnapshot()
        .getAllUsedNonOvershadowedSegments(TestDataSource.WIKI, theInterval);
    Assert.assertEquals(Set.of(wikiSegment1, wikiSegment3), segments);
  }

