@Test
  public void testSelectWithLoadedSegmentsOnFooWithOrderBy()
  {
    RowSignature resultSignature = RowSignature.builder()
                                               .add("cnt", ColumnType.LONG)
                                               .add("dim1", ColumnType.STRING)
                                               .build();

    doAnswer(
        invocationOnMock -> {
          ScanQuery query = invocationOnMock.getArgument(0);
          ScanQuery.verifyOrderByForNativeExecution(query);
          Assert.assertEquals(Long.MAX_VALUE, query.getScanRowsLimit());
          return new DataServerQueryResult<>(
              ImmutableList.of(
                  Yielders.each(
                      Sequences.simple(
                          ImmutableList.of(
                              new Object[]{1L, "qwe"},
                              new Object[]{1L, "tyu"}
                          )
                      )
                  )),
              ImmutableList.of(),
              "foo"
          );
        }
    )
        .when(dataServerQueryHandler)
        .fetchRowsFromDataServer(any(), any(), any());

    testSelectQuery()
        .setSql("select cnt, dim1 from foo order by dim1")
        .setExpectedMSQSpec(
            MSQSpec.builder()
                   .query(
                       newScanQueryBuilder()
                           .dataSource(CalciteTests.DATASOURCE1)
                           .intervals(querySegmentSpec(Filtration.eternity()))
                           .columns("cnt", "dim1")
                           .columnTypes(resultSignature.getColumnTypes())
                           .orderBy(ImmutableList.of(OrderBy.ascending("dim1")))
                           .context(defaultScanQueryContext(REALTIME_QUERY_CTX, resultSignature))
                           .build()
                   )
                   .columnMappings(ColumnMappings.identity(resultSignature))
                   .tuningConfig(MSQTuningConfig.defaultConfig())
                   .destination(TaskReportMSQDestination.INSTANCE)
                   .build()
        )
        .setQueryContext(REALTIME_QUERY_CTX)
        .setExpectedRowSignature(resultSignature)
        .setExpectedResultRows(ImmutableList.of(
            new Object[]{1L, ""},
            new Object[]{1L, "1"},
            new Object[]{1L, "10.1"},
            new Object[]{1L, "2"},
            new Object[]{1L, "abc"},
            new Object[]{1L, "def"},
            new Object[]{1L, "qwe"},
            new Object[]{1L, "tyu"}
        ))
        .verifyResults();
  }

